const alloyBases = [
  ['Mg', 'Magnesium', 24.305], ['Al', 'Aluminum', 26.9815384],
  ['Ti', 'Titanium', 47.867], ['Fe', 'Iron', 55.845],
  ['Co', 'Cobalt', 58.933194], ['Ni', 'Nickel', 58.6934],
  ['Cu', 'Copper', 63.546], ['Zn', 'Zinc', 65.38],
  ['Zr', 'Zirconium', 91.222], ['Ag', 'Silver', 107.8682],
