"""Material-point processing schedules and equilibrium inputs."""
from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from rutile3.domain.selection import Element


class AdditionBound(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)
    element: Element
    minimum: float = Field(default=0, ge=0, lt=100)
    maximum: float = Field(gt=0, lt=100)

    @model_validator(mode="after")
    def check_bounds(self):
        self.element = self.element.upper()
        if self.minimum > self.maximum:
            raise ValueError("Minimum addition must not exceed maximum.")
        return self


class ProcessingEvent(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)


class TemperatureChange(ProcessingEvent):
    kind: Literal["temperature_change"]
    temperature_k: float = Field(ge=273.15, le=4000)
    duration_s: float | None = Field(default=None, gt=0)


class Anneal(ProcessingEvent):
    kind: Literal["anneal"]
    temperature_k: float = Field(ge=273.15, le=2500)
    hold_s: float = Field(gt=0)


class Quench(ProcessingEvent):
    kind: Literal["quench"]
    medium: Literal["water", "oil", "air", "brine"]
    temperature_k: float = Field(ge=273.15, le=2500)


class ColdWork(ProcessingEvent):
    kind: Literal["cold_work"]
    reduction_pct: float = Field(gt=0, lt=100)


ScheduleEvent = Annotated[TemperatureChange | Anneal | Quench | ColdWork, Field(discriminator="kind")]


class ProcessingRequest(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)
    family: Literal["AL", "FE", "NI"]
    database_id: str | None = Field(default=None, max_length=64)
    composition_basis: Literal["mass", "atomic"] = "mass"
    composition_mode: Literal["bounds", "fixed"] = "bounds"
    additions: list[AdditionBound] = Field(min_length=1, max_length=8)
    route: Literal["arc_melting", "heat_treatment"] = "arc_melting"
    cooling_model: Literal["equilibrium"] = "equilibrium"
    phase_policy: Literal["all_compatible", "fe_cementite"] = "all_compatible"
    initial_temperature_k: float = Field(default=298.15, ge=273.15, le=2500)
    melt_temperature_k: float = Field(default=1873.15, ge=273.15, le=4000)
    final_temperature_k: float = Field(default=298.15, ge=273.15, le=2500)
    pressure_pa: float = Field(default=101325, gt=0, le=1e9)
    cooling_points: int = Field(default=21, ge=3, le=61)
    events: list[ScheduleEvent] = Field(default_factory=list, max_length=24)
    notes: str = Field(default="", max_length=2000)
    include_reference_properties: bool = True
    allow_screening_estimates: bool = True
    use_physical_density: bool = True

    @model_validator(mode="after")
    def check_cycle(self):
        elements = [bound.element for bound in self.additions]
        if len(elements) != len(set(elements)) or self.family in elements:
            raise ValueError("Choose distinct additions and exclude the base element.")
        if self.phase_policy == "fe_cementite" and (self.family != "FE" or elements != ["C"]):
            raise ValueError("Fe–Fe₃C equilibrium requires iron with carbon as its sole addition.")
        if sum(bound.maximum for bound in self.additions) >= 100:
            raise ValueError("Maximum additions must leave a positive base balance.")
        if self.composition_mode == "fixed" and any(bound.minimum != bound.maximum for bound in self.additions):
            raise ValueError("Fixed composition requires equal minimum and maximum amounts.")
        if self.route == "arc_melting" and self.melt_temperature_k <= max(self.initial_temperature_k, self.final_temperature_k):
            raise ValueError("The melt temperature must exceed initial and final temperatures.")
        if self.route == "heat_treatment" and not self.events:
            raise ValueError("Add a processing event for heat treatment or cold work.")
        temperature = self.final_temperature_k if self.route == "arc_melting" else self.initial_temperature_k
        for index, event in enumerate(self.events):
            if isinstance(event, ColdWork):
                if index != len(self.events) - 1:
                    raise ValueError("Cold work must be the last processing event.")
                continue
            if isinstance(event, Quench) and event.temperature_k >= temperature:
                raise ValueError("The quench temperature must be below the preceding temperature.")
            temperature = event.temperature_k
        return self

    def nominal_percent(self):
        values = {bound.element: bound.maximum * (1 if self.composition_mode == "fixed" else .5) for bound in self.additions}
        return {self.family: 100 - sum(values.values()), **values}
"""Auditable syntax conversion of MatCalc sources; originals remain immutable.

This is an equilibrium adapter, not an implementation of MatCalc's vacancy,
coherent-strain, phase-priority or composition-set initialization models.
"""
from collections import Counter
from itertools import product
import re

from pycalphad.io.tdb_keywords import TDB_PARAM_TYPES

from rutile3.engines.tdb import parse_tdb


def text(raw):
    try:
        return raw.decode("utf-8-sig")
    except UnicodeDecodeError:
        return raw.decode("cp1252")


def convert(raw, *, mobility=False):
    content = text(raw)
    if not mobility and not re.search(r"(?m)^\s*REFERENCE_ELEMENT\b", content):
        return raw, {"adapter": "native TDB", "changes": {}}
    changes = Counter()
    # Comments are preserved in source.tdb/source.ddb, including license terms.
    content = "\n".join(line.split("$")[0] for line in content.splitlines())
    content = re.split(r"(?m)^\s*(?:LIST_OF_REFERENCES|A00201-0)\b", content)[0]
    content, changes["reference_annotations_removed"] = re.subn(r"\bREF\b\s*:?\s*[^\s!]+", "", content, flags=re.I)
    # Explicit source errata found in mc_fe_v2062 / mc_ni_v2036 / mc_al_v2008.
    # Do not make general numerical corrections to arbitrary expressions.
    for old, new in (("G(G_PHASE;", "G(G_PHASE,"), ("6000.00.00", "6000.00"),
                     ("273.00 273 +46000", "273.00 +46000"), ("N ; 6000.00  N", "N"),
                     ("-0,6*QAL_FCC", "-0.6*QAL_FCC")):
        if old in content:
            changes[f"source_erratum: {old} -> {new}"] = content.count(old)
            content = content.replace(old, new)
    content, changes["missing_parameter_terminators_inserted"] = re.subn(
        r"(?<=N)\s*\n(?=PARAM(?:ETER)?\s)", " !\n", content)
    commands, links, initialization = [], [], []
    allowed = {"ELEMENT", "SPECIES", "FUNCTION", "PHASE", "CONSTITUENT", "CONST", "PARAMETER", "PARAM", "TYPE_DEFINITION", "DIFFUSION"}
    for command in content.split("!"):
        command = command.strip()
        if not command:
            continue
        head = command.split()[0].upper()
        if head in {"REFERENCE_ELEMENT", "ADD_COMPOSITION_SET"}:
            initialization.append(command)
            changes[f"{head}_metadata_retained_separately"] += 1
            continue
        if head == "ATTACH_CONTRIBUTION":
            _, ordered, disordered, kind = command.split()
            if kind != "ORDER_DISORDER":
                raise ValueError(f"Unsupported MatCalc contribution: {command}")
            links.append((ordered, disordered))
            continue
        if head not in allowed:
            raise ValueError(f"Unsupported MatCalc command: {head}")
        if head in {"PHASE", "CONSTITUENT", "CONST"} and ">" in command:
            command = command.split(">")[0].rstrip()
            changes["display_annotations_removed"] += 1
        match = re.match(r"PARAM(?:ETER)?\s+(\w+)\(", command)
        if match and match[1] not in TDB_PARAM_TYPES:
            if match[1] not in {"HMVA", "SE"}:
                raise ValueError(f"Unsupported physical parameter: {match[1]}")
            changes[f"{match[1]}_not_used_in_equilibrium"] += 1
            continue
        commands.append(command + " !")
    if not mobility:
        commands.insert(0, "TYPE_DEFINITION % SEQ * !")
    for index, (ordered, disordered) in enumerate(links):
        marker = "@~?"[index]
        if any(re.match(r"TYPE_DEFINITION\s+" + re.escape(marker) + r"\s", c) for c in commands):
            raise ValueError("Ordering type-definition marker is already occupied.")
        commands = [re.sub(r"^(PHASE\s+" + ordered + r"\s+\S+)", r"\1" + marker, c) for c in commands]
        commands.append(f"TYPE_DEFINITION {marker} GES A_P_D {ordered} DIS_PART {disordered} !")
        changes["order_disorder_links_translated"] += 1
    converted = ("\n".join(commands) + "\n").encode("utf-8")
    return converted, {"adapter": "MatCalc equilibrium syntax v1", "changes": dict(changes),
                       "initialization_metadata": initialization,
                       "limitations": ["MatCalc phase priorities and composition-set seeds are not solver constraints.",
                                       "HMVA vacancy and SE coherent-strain corrections are not modeled."]}


def attach_mobility(db, raw, phase, components):
    """Explicitly attach the companion's mobility parameters to one matrix.

    MatCalc wildcard defaults are fallbacks, not additive endmembers. Expand
    them over active endmembers and prefer specific entries before Kawin sums
    the Redlich-Kister terms. No Gibbs-energy parameters are imported.
    """
    from pycalphad import Model, variables as v
    converted, report = convert(raw, mobility=True)
    diffusion = parse_tdb(converted)
    for symbol, value in diffusion.symbols.items():
        if symbol in db.symbols and db.symbols[symbol] != value:
            raise ValueError(f"Mobility function conflicts with thermodynamic function {symbol}.")
        db.symbols[symbol] = value
    candidates = diffusion._parameters.all()
    if any(p["parameter_type"] not in {"MQ", "MF", "DQ", "DF"} for p in candidates):
        raise ValueError("Companion contains non-mobility parameters; automatic attachment refused.")
    model = Model(db, components, phase)
    constituents = [sorted(sublattice, key=str) for sublattice in model.constituents]
    selected = [p for p in candidates if p["phase_name"] == phase]
    covered = set()
    for element in set(components) - {"VA"}:
        records = [p for p in selected if str(p["diffusing_species"]) == element]
        if not records:
            raise ValueError(f"No mobility data for {element} in {phase}.")
        covered_endmembers = set()
        for kind in sorted({p["parameter_type"] for p in records}):
            terms = [p for p in records if p["parameter_type"] == kind]
            endmembers = [p for p in terms if all(len(sl) == 1 for sl in p["constituent_array"]) and p["parameter_order"] == 0]
            for endmember in product(*constituents):
                matches = []
                for parameter in endmembers:
                    array = parameter["constituent_array"]
                    if len(array) > len(endmember):
                        continue
                    if all(str(sl[0]) == "*" or sl[0] == endmember[i] for i, sl in enumerate(array)):
                        specificity = sum(str(sl[0]) != "*" for sl in array)
                        matches.append((specificity, parameter))
                if not matches:
                    if kind == "MQ":
                        raise ValueError(f"Missing {element} mobility endmember in {phase}: {endmember}")
                    continue
                specificity = max(score for score, _ in matches)
                best = [p for score, p in matches if score == specificity]
                if any(p["parameter"] != best[0]["parameter"] for p in best):
                    raise ValueError(f"Ambiguous mobility defaults for {element} in {phase}.")
                db.add_parameter(kind, phase, [[str(s)] for s in endmember], 0, best[0]["parameter"],
                                 diffusing_species=element)
                covered.add(element)
                covered_endmembers.add(tuple(endmember))
            for parameter in terms:
                if parameter in endmembers:
                    continue
                array = parameter["constituent_array"]
                if len(array) > len(constituents):
                    raise ValueError("Mobility and thermodynamic sublattice counts do not match.")
                if any(not set(sl).issubset(constituents[i]) for i, sl in enumerate(array)):
                    continue
                padded = list(array) + [(v.Species("*"),)] * (len(constituents) - len(array))
                db.add_parameter(kind, phase, [[str(s) for s in sl] for sl in padded], parameter["parameter_order"], parameter["parameter"],
                                 diffusing_species=element)
        if any(tuple(endmember) not in covered_endmembers for endmember in product(*constituents)):
            raise ValueError(f"Incomplete kinetic endmember coverage for {element} in {phase}.")
    report["active_phase"] = phase
    report["elements_with_mobility"] = sorted(covered)
    report["wildcard_policy"] = "Expand fallback defaults over active endmembers; specific entries override defaults."
    return converted, report

"""Persistent metadata for read-only TDB sources and exact-content selections."""
from contextlib import contextmanager
import hashlib
from importlib.metadata import version
import json
import os
from pathlib import Path
import sqlite3
from threading import Event, Lock, Thread
from tempfile import NamedTemporaryFile
import warnings

from rutile3.engines.tdb import describe

PROJECT_ROOT = Path(__file__).resolve().parents[4]
WORKSPACE = Path(os.environ.get("RUTILE_WORKSPACE", PROJECT_ROOT / "workspace")).resolve()
BUNDLED_SOURCE_ROOT = PROJECT_ROOT / "data" / "matcalc"
SOURCE_ROOT = Path(os.environ.get("RUTILE_DATABASE_ROOT", BUNDLED_SOURCE_ROOT))
PARSER = f"pycalphad {version('pycalphad')} / catalog 2"
SUFFIXES = {".tdb", ".tbd"}
SCHEMA = """
CREATE TABLE IF NOT EXISTS roots (path TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS versions (id TEXT PRIMARY KEY, parser TEXT, metadata TEXT);
CREATE TABLE IF NOT EXISTS locations (
    path TEXT, id TEXT, root TEXT, available INTEGER NOT NULL,
    PRIMARY KEY (path, id)
);
CREATE TABLE IF NOT EXISTS scan_findings (
    root TEXT, path TEXT, message TEXT, PRIMARY KEY (root, path)
);
CREATE TABLE IF NOT EXISTS preferences (
    scope TEXT, system TEXT, capability TEXT, id TEXT NOT NULL,
    PRIMARY KEY (scope, system, capability)
);
CREATE TABLE IF NOT EXISTS evidence (
    id TEXT, system TEXT, capability TEXT, metadata TEXT NOT NULL,
    PRIMARY KEY (id, system, capability)
);
"""


def checksum(raw):
    return hashlib.sha256(raw).hexdigest()


def system_key(components):
    return "-".join(sorted(components))


class Catalog:
    def __init__(self, database_path=None, workspace=None, source_root=None):
        self.workspace = Path(workspace or WORKSPACE)
        self.source_root = Path(source_root or SOURCE_ROOT)
        local = Path(os.environ.get("LOCALAPPDATA") or Path.home() / ".local" / "share")
        workspace_id = checksum(os.fsencode(self.workspace.resolve()))[:16]
        default = local / "Rutile3" / workspace_id / "catalog.sqlite3"
        self.database_path = Path(database_path or os.environ.get("RUTILE_CATALOG_PATH") or default)
        self.scan_lock = Lock()
        self.scan_cancel = Event()
        self.scan_state = {"state": "idle", "processed": 0}
        self.scan_thread = None

    @contextmanager
    def connect(self):
        self.database_path.parent.mkdir(parents=True, exist_ok=True)
        db = sqlite3.connect(self.database_path, timeout=30)
        db.row_factory = sqlite3.Row
        try:
            db.executescript(SCHEMA)
            with db:
                yield db
        finally:
            db.close()

    def roots(self):
        with self.connect() as db:
            registered = [Path(row["path"]) for row in db.execute("SELECT path FROM roots ORDER BY path")]
        return list(dict.fromkeys([self.source_root.resolve(), *registered, (self.workspace / "imports").resolve()]))

    def register_root(self, directory):
        root = Path(directory)
        if not root.is_absolute() or not root.is_dir():
            raise ValueError("Enter an existing absolute directory path.")
        with self.connect() as db:
            db.execute("INSERT OR IGNORE INTO roots VALUES (?)", (str(root.resolve()),))

    def start_scan(self):
        with self.scan_lock:
            if self.scan_thread and self.scan_thread.is_alive():
                return self.scan_state
            self.scan_cancel.clear()
            self.scan_state = {"state": "running", "processed": 0}
            self.scan_thread = Thread(target=self.scan, daemon=True)
            self.scan_thread.start()
            return self.scan_state

    def stop_scan(self, wait=False):
        self.scan_cancel.set()
        if wait and self.scan_thread:
            self.scan_thread.join()
        return self.scan_state

    def metadata(self, raw):
        key = checksum(raw)
        with self.connect() as db:
            row = db.execute("SELECT metadata FROM versions WHERE id=? AND parser=?", (key, PARSER)).fetchone()
        if row:
            return key, json.loads(row["metadata"])
        return key, self.parse_metadata(raw)

    @staticmethod
    def parse_metadata(raw):
        with warnings.catch_warnings(record=True) as notes:
            try:
                metadata = describe(raw)
            except Exception as exc:
                metadata = {"parse_error": f"{type(exc).__name__}: {exc}", "elements": [], "phases": [],
                            "parameter_types": [], "capabilities": [], "has_gibbs_energy": False}
        metadata["parser_warnings"] = list(dict.fromkeys(str(note.message) for note in notes))
        return metadata

    def scan(self):
        processed = 0
        try:
            with self.connect() as db:
                cache = {row["id"]: json.loads(row["metadata"]) for row in db.execute(
                    "SELECT id, metadata FROM versions WHERE parser=?", (PARSER,))}
            for root in self.roots():
                if self.scan_cancel.is_set():
                    break
                discovered, failures = {}, {}
                with self.connect() as db:
                    previous = [tuple(row) for row in db.execute(
                        "SELECT path, id FROM locations WHERE root=? AND available=1", (str(root),))]
                if root.is_dir():
                    def on_error(error):
                        failures[str(error.filename or root)] = str(error)

                    for directory, _, filenames in os.walk(root, onerror=on_error):
                        for filename in filenames:
                            if self.scan_cancel.is_set():
                                break
                            path = Path(directory) / filename
                            if path.suffix.lower() not in SUFFIXES:
                                continue
