"""Material-point equilibrium along a processing schedule, with optional transport context."""
from datetime import datetime, timezone
from importlib.metadata import version
import math
from pathlib import Path
from time import monotonic
import warnings

import numpy as np
from pycalphad import equilibrium, variables as v
from pycalphad.codegen.phase_record_factory import PhaseRecordFactory

from rutile3.data.catalog import checksum
from rutile3.data.processing import validate_phase_policy_source
from rutile3.domain.processing import ColdWork, ProcessingRequest
from rutile3.engines.binary import phase_instances
from rutile3.engines.matcalc import attach_mobility, convert
from rutile3.engines.tdb import available_phases, parse_tdb, solver_models


# MatCalc Fe 2.062 represents disordered ferrite through BCC_B2's linked BCC_A2
# contribution. In binary Fe–C the substitutional ordering sites only contain Fe.
STEEL_PHASE_NAMES = {"BCC_B2": "Ferrite", "CEMENTITE": "Cementite", "FCC_A1": "Austenite", "LIQUID": "Liquid"}


class ProcessingPhaseRecords(PhaseRecordFactory):
    """Normalize NumPy phase labels at the pycalphad/Cython boundary.

    Multicomponent equilibrium can request a previously unseen np.str_ label;
    the upstream PhaseRecord constructor requires a native Python str.
    """
    def get(self, phase_name):
        return super().get(str(phase_name))

    __getitem__ = get


def nominal_composition(request, db):
    percentages = request.nominal_percent()
    missing = set(percentages) - db.elements
    if missing:
        raise ValueError(f"Thermodynamic source is missing selected elements: {', '.join(sorted(missing))}.")
    if request.composition_basis == "mass":
        masses = {element: float(db.refstates[element]["mass"]) for element in percentages}
        if any(not math.isfinite(mass) or mass <= 0 for mass in masses.values()):
            raise ValueError("The TDB does not provide valid atomic masses for mass-to-mole conversion.")
        amounts = {element: value / masses[element] for element, value in percentages.items()}
    else:
        masses = None
        amounts = percentages
    total = sum(amounts.values())
    return {"input_basis": request.composition_basis, "nominal_percent": percentages,
            "mole_fraction": {element: amount / total for element, amount in amounts.items()},
            "atomic_masses_g_mol": masses, "rule": (
                "Exact entered additions; base is balance." if request.composition_mode == "fixed" else
                "Each selected addition is 0.5 × its maximum; base is balance.")}


def phase_state(eq, composition, temperature, stage):
    order = [str(component) for component in eq.component.values]
    phases = phase_instances(eq.Phase.values.reshape(-1), eq.NP.values.reshape(-1),
                             eq.X.values.reshape(-1, len(order)), order)
    gibbs = float(eq.GM.values.item())
    if not phases or not math.isfinite(gibbs):
        raise ValueError(f"Equilibrium did not converge at {temperature:g} K ({stage}).")
    total = sum(phase["fraction"] for phase in phases)
    errors = {element: sum(p["fraction"] * p["composition"][element] for p in phases) - value
              for element, value in composition.items()}
    if abs(total - 1) > 1e-5 or any(abs(error) > 1e-5 for error in errors.values()):
        raise ValueError(f"Equilibrium failed phase-amount or elemental balance at {temperature:g} K.")
    return {"stage": stage, "temperature_k": float(temperature), "phases": phases,
            "gibbs_energy_j_mol": gibbs, "phase_fraction_basis": "mole",
            "composition_basis": "mole_fraction", "balance_errors": errors}


def substitutional_disorder(eq, db, model, composition):
    """Classify a final phase using its active constituents and solver site fractions."""
    hints = db.phases[model.phase_name].model_hints
    parent = hints.get("disordered_phase") if hints.get("ordered_phase") == model.phase_name else None
    vacancy = {v.Species("VA")}
    active_species = set(model.components)
    constituents = ([set(sl) & active_species for sl in db.phases[parent].constituents]
                    if parent else [set(sl) for sl in model.constituents])
    if (any(species.number_of_atoms != 1 or species.charge for species in constituents[0] - vacancy)
            or any(sl - vacancy for sl in constituents[1:])):
        return {"state": "unsupported_sublattices", "parent": parent}
"""Local physical-source modeling followed by optional network references."""
import math

from rutile3.data.catalog import WORKSPACE
from rutile3.engines.physical_density import PhysicalDensity, DensityUnavailable
from rutile3.engines.tdb import parse_tdb
from rutile3.jobs.storage import write_json
from rutile3.services.property_estimates import estimate_properties


def calculate_properties(folder, result, *, api_key=None):
    db = parse_tdb((folder / "solver.tdb").read_bytes())
    masses = {e: float(db.refstates[e]["mass"]) for e in result["composition"]["mole_fraction"]}
    if any(not math.isfinite(m) or m <= 0 for m in masses.values()):
        raise ValueError("Invalid atomic masses for physical-property calculations.")
    models, report = {}, {"state": "unavailable", "reason": "No physical density source was supplied."}
    path = folder / "physical-source.pdb"
    settings = result["settings"]
    if not settings.get("use_physical_density", True):
        report = {"state": "unavailable", "reason": "Local physical density was disabled for this run."}
    if settings.get("use_physical_density", True) and path.exists():
        try:
            source = PhysicalDensity(path.read_bytes())
            report = {"state": "loaded", "source_sha256": source.sha256,
                      "source_name": "physical-source.pdb", "units": "kg/m³ (converted to g/cm³ for display)",
                      "functions": len(source.functions), "parameters": len(source.parameters),
                      "changes": dict(source.changes),
                      "wildcard_defaults_excluded": sum(p["wildcard"] for p in source.parameters),
                      "limitations": ["Only supported substitutional models with explicit endmember coverage are evaluated.",
                                      "No generic wildcard defaults, interstitial-density, pressure, or porosity corrections.",
                                      "Source formula temperature bounds do not establish experimentally validated applicability.",
                                      "Density interpolation has not been benchmarked against MatCalc software or published alloy measurements."]}
            for phase in result["final"]["phases"]:
                try:
                    models[phase["label"]] = source.phase_density(phase, db, result["final"]["temperature_k"],
                        allow_parent=settings.get("allow_screening_estimates", True))
                except DensityUnavailable as exc:
                    models[phase["label"]] = {"state": "unavailable", "reason": str(exc)}
            write_json(folder / "physical-density-model.json", {**report, "phase_models": models})
        except Exception as exc:
            report = {"state": "unavailable", "reason": f"Physical density source could not be interpreted: {exc}"}
    client = None
    if settings.get("include_reference_properties", True) and api_key:
        from rutile3.data.materials_project import MaterialsProject
        client = MaterialsProject(api_key, WORKSPACE / "reference-cache" / "materials-project")
    estimates = estimate_properties(result, masses, client, density_models=models)
    estimates["physical_density"] = report
    estimates["atomic_masses_g_mol"] = masses
    return estimates
@app.get("/api/processing/sources")
