        job_id = jobs.start(path, body.model_dump(mode="json"), decision,
                            snapshot=raw, kind="processing", mobility=mobility,
                            physical=physical,
                            api_key=session_key or os.environ.get("MP_API_KEY"))
        return {"id": job_id}
    except (ValueError, OSError) as exc:
