$qa = Join-Path (Get-Location).Path 'workspace\push-browser'
New-Item -ItemType Directory -Path $qa -Force | Out-Null
$env:RUTILE_WORKSPACE = $qa
$env:RUTILE_CATALOG_PATH = Join-Path $qa 'catalog.sqlite3'
$env:RUTILE_DATABASE_ROOT = (Resolve-Path 'data/matcalc').Path
$env:MP_API_KEY = ' '
$env:RUTILE_TEST_URL = 'http://127.0.0.1:8084'
$python = 'Y:\Rutile3\.venv\Scripts\python.exe'
$server = Start-Process -FilePath $python -ArgumentList @('scripts/run_app.py','--port','8084') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $qa 'server.out') -RedirectStandardError (Join-Path $qa 'server.err')
try {
    for ($attempt = 0; $attempt -lt 60; $attempt++) {
        if ($server.HasExited) { throw "Test server exited. See $qa\server.err." }
        try {
            $response = Invoke-WebRequest -UseBasicParsing "$env:RUTILE_TEST_URL/api/processing/sources" -TimeoutSec 2
            if ($response.StatusCode -eq 200) { break }
        } catch { Start-Sleep -Milliseconds 500 }
    }
    & $python -u scripts/check_optimizer_ui.py
    $uiExit = $LASTEXITCODE
    & $python -u scripts/check_processing_workflow.py --matcalc
    $processingExit = $LASTEXITCODE
    if ($uiExit -ne 0 -or $processingExit -ne 0) { exit 1 }
} finally {
    if (!$server.HasExited) { Stop-Process -Id $server.Id }
}

